const LANGS = [['en','EN'],['tr','TR'],['es','ES'],['it','IT'],['pt','PT'],['fr','FR']];

function getLang() {
  const saved = localStorage.getItem('hostlio_lang');
  if (saved && I18N[saved]) return saved;
  const browser = (navigator.language || 'en').slice(0, 2).toLowerCase();
  return I18N[browser] ? browser : 'en';
}

function applyLang(lang) {
  const dict = I18N[lang] || I18N.en;
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (dict[key]) el.innerHTML = dict[key];
  });
  localStorage.setItem('hostlio_lang', lang);
  document.documentElement.lang = lang;
  document.querySelectorAll('.lang-btn').forEach(b => {
    b.classList.toggle('active', b.getAttribute('data-lang') === lang);
  });
}

function buildLangSwitcher() {
  const wrap = document.getElementById('lang-switcher');
  if (!wrap) return;
  wrap.innerHTML = LANGS.map(([code, label]) =>
    `<button class="lang-btn" data-lang="${code}">${label}</button>`).join('');
  wrap.querySelectorAll('.lang-btn').forEach(b => {
    b.addEventListener('click', () => applyLang(b.getAttribute('data-lang')));
  });
}

document.addEventListener('DOMContentLoaded', () => {
  buildLangSwitcher();
  applyLang(getLang());
});
